72	// refBase resolves a checkpoint ref's current tip commit (the parent for the
73	// next write) and subtree object (the checkpoint's current contents). A missing
74	// ref yields (ZeroHash, nil) so the next write becomes an orphan commit.
75	func (s *gitRefsStore) refBase(cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
76		refName, err := RefName(cid)
77		if err != nil {
78			return plumbing.ZeroHash, nil, err
79		}
80		ref, err := s.repo.Reference(refName, true)
81		if errors.Is(err, plumbing.ErrReferenceNotFound) {
82			return plumbing.ZeroHash, nil, nil // no ref yet → new checkpoint (orphan)
83		}
84		if err != nil {
85			// A real lookup failure (IO/corruption), not an absent ref: surface it
86			// rather than silently starting a fresh orphan history over the ref.
87			return plumbing.ZeroHash, nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
88		}
89		commit, err := s.repo.CommitObject(ref.Hash())
90		if err != nil {
91			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
92		}
93		tree, err := commit.Tree()
94		if err != nil {
95			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
96		}
97		return ref.Hash(), tree, nil
98	}
