360	// recent first. Storage-level listing is local-refs-only for now (no remote
361	// enumeration), matching the issue's first-version scope.
362	func (s *gitRefsStore) List(ctx context.Context) ([]CheckpointInfo, error) {
363		if err := ctx.Err(); err != nil {
364			return nil, err //nolint:wrapcheck // Propagating context cancellation
365		}
366	
367		refs, err := s.repo.References()
368		if err != nil {
369			return nil, fmt.Errorf("list checkpoint refs: %w", err)
370		}
371		defer refs.Close()
372	
373		var checkpoints []CheckpointInfo
374		err = refs.ForEach(func(ref *plumbing.Reference) error {
375			cid, ok := ParseRef(ref.Name())
376			if !ok {
377				return nil
378			}
379			commit, commitErr := s.repo.CommitObject(ref.Hash())
380			if commitErr != nil {
381				return nil //nolint:nilerr // skip unreadable refs, keep listing
382			}
383			tree, treeErr := commit.Tree()
384			if treeErr != nil {
385				return nil //nolint:nilerr // skip unreadable refs, keep listing
386			}
387			checkpoints = append(checkpoints, readCommittedInfoFromCheckpointTree(cid, tree))
388			return nil
389		})
390		if err != nil {
391			return nil, fmt.Errorf("iterate checkpoint refs: %w", err)
392		}
