84	// Drain returns the de-duplicated refs currently queued, in first-seen order. It
85	// does NOT remove them; call Remove after a confirmed push so a failed push
86	// retries next time. A missing queue file yields no refs.
87	//
88	// It compacts the file in place: when the on-disk queue held redundant lines
89	// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
90	// it to the de-duplicated set. Enqueue only ever appends, so without this the
91	// file would grow unboundedly between the Removes that are otherwise the sole
92	// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
93	// checkpoint ref but never pushes).
94	func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
95		release, err := flock.Acquire(q.lockPath())
96		if err != nil {
97			return nil, fmt.Errorf("lock push queue: %w", err)
98		}
99		defer release()
100	
101		refs, rawLines, err := q.readLocked()
102		if err != nil {
103			return nil, err
104		}
105		if rawLines > len(refs) {
106			if err := q.rewriteLocked(refs); err != nil {
107				return nil, err
108			}
109		}
110		return refs, nil
111	}
112	
113	// Remove deletes the given refs from the queue, preserving any entries appended
114	// after a Drain (e.g. a write that landed during the push). Called after a
115	// confirmed push.
116	func (q *PushQueue) Remove(refs []plumbing.ReferenceName) error {
117		if len(refs) == 0 {
118			return nil
119		}
120		release, err := flock.Acquire(q.lockPath())
121		if err != nil {
122			return fmt.Errorf("lock push queue: %w", err)
123		}
124		defer release()
125	
126		current, _, err := q.readLocked()
127		if err != nil {
128			return err
129		}
130		removed := make(map[string]struct{}, len(refs))
131		for _, r := range refs {
132			removed[r.String()] = struct{}{}
133		}
134		kept := make([]plumbing.ReferenceName, 0, len(current))
135		for _, r := range current {
136			if _, drop := removed[r.String()]; drop {
137				continue
138			}
139			kept = append(kept, r)
140		}
141		return q.rewriteLocked(kept)
142	}
143	
144	// rewriteLocked replaces the queue file with exactly refs (de-duplicated, one
145	// line each), or removes the file when refs is empty so a clean repo has no
146	// stray queue. The caller must hold the lock. The write is atomic (temp file +
147	// rename) so a concurrent reader never sees a half-written queue.
148	func (q *PushQueue) rewriteLocked(refs []plumbing.ReferenceName) error {
149		if len(refs) == 0 {
150			if err := os.Remove(q.queuePath()); err != nil && !os.IsNotExist(err) {
151				return fmt.Errorf("remove empty push queue: %w", err)
152			}
153			return nil
154		}
155		var buf bytes.Buffer
156		for _, r := range refs {
157			line, err := json.Marshal(pushQueueEntry{Ref: r.String()})
158			if err != nil {
159				return fmt.Errorf("encode push queue entry: %w", err)
160			}
161			buf.Write(line)
162			buf.WriteByte('\n')
163		}
164		if err := writeFileAtomicInDir(q.dir, q.queuePath(), buf.Bytes()); err != nil {
165			return fmt.Errorf("rewrite push queue: %w", err)
166		}
167		return nil
168	}
169	
170	// readLocked parses the queue file into de-duplicated refs, preserving first-seen
171	// order. The caller must hold the lock. Malformed lines are skipped rather than
172	// failing the whole drain — a single bad record must not strand every queued ref.
173	//
174	// rawLines is the number of non-empty lines seen (including duplicates and
175	// malformed records), so callers can detect when the file holds more than the
176	// de-duplicated set and is worth compacting: rawLines > len(refs) exactly when
177	// there were redundant lines.
178	func (q *PushQueue) readLocked() (refs []plumbing.ReferenceName, rawLines int, err error) {
179		f, err := os.Open(q.queuePath())
180		if err != nil {
181			if os.IsNotExist(err) {
182				return nil, 0, nil
183			}
184			return nil, 0, fmt.Errorf("open push queue: %w", err)
185		}
186		defer f.Close()
187	
188		seen := make(map[string]struct{})
189		scanner := bufio.NewScanner(f)
190		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
191		for scanner.Scan() {
192			line := bytes.TrimSpace(scanner.Bytes())
193			if len(line) == 0 {
194				continue
195			}
196			rawLines++
197			var entry pushQueueEntry
198			if err := json.Unmarshal(line, &entry); err != nil || entry.Ref == "" {
199				continue
200			}
201			if _, dup := seen[entry.Ref]; dup {
202				continue
203			}
204			seen[entry.Ref] = struct{}{}
205			refs = append(refs, plumbing.ReferenceName(entry.Ref))
206		}
207		if err := scanner.Err(); err != nil {
208			return nil, 0, fmt.Errorf("read push queue: %w", err)
209		}
210		return refs, rawLines, nil
211	}
212	
213	// writeFileAtomicInDir writes data to a temp file in dir and renames it over
214	// path, so a reader (under the lock) never sees a half-written queue.
215	func writeFileAtomicInDir(dir, path string, data []byte) error {
216		tmp, err := os.CreateTemp(dir, pushQueueFileName+".*")
217		if err != nil {
218			return fmt.Errorf("create temp push queue: %w", err)
219		}
220		tmpName := tmp.Name()
221		defer os.Remove(tmpName)
222		if _, err := tmp.Write(data); err != nil {
223			_ = tmp.Close()
224			return fmt.Errorf("write temp push queue: %w", err)
225		}
226		if err := tmp.Close(); err != nil {
227			return fmt.Errorf("close temp push queue: %w", err)
228		}
229		if err := os.Rename(tmpName, path); err != nil {
230			return fmt.Errorf("rename temp push queue: %w", err)
231		}
232		return nil
233	}
