46	func Compare(a, b CheckpointFormat) int {
47		aRank := familyRank(a.Family)
48		bRank := familyRank(b.Family)
49		if aRank != bRank {
50			return cmp.Compare(aRank, bRank)
51		}
52		if a.Family != b.Family {
53			return cmp.Compare(string(a.Family), string(b.Family))
54		}
55		return cmp.Compare(a.Major, b.Major)
56	}
